// Recursive function to find the nth number in the sequence
long long customSequenceRecursive(int n) {
    // Base Cases
    if (n == 0) return 0;
    if (n == 1) return -1;
    if (n == 2) return -1;

    // Recursive Step: T(n) = T(n-1) + T(n-2) + T(n-3)
    return customSequenceRecursive(n - 1) + 
           customSequenceRecursive(n - 2) + 
           customSequenceRecursive(n - 3);
}

// Iterative function to find the nth number (Much faster)
long long customSequenceIterative(int n) {
    if (n == 0) return 0;
    if (n == 1 || n == 2) return -1;

    long long t0 = 0, t1 = -1, t2 = -1;
    long long tn = 0;

    for (int i = 3; i <= n; i++) {
        tn = t0 + t1 + t2; // Sum of three preceding
        t0 = t1;           // Shift values forward
        t1 = t2;
        t2 = tn;
    }
    return tn;
}

