	end := idx2
	if idx1 > idx2 {
		start = idx2
		end = idx1
	}

	// The planets "between" are from start + 1 up to (but not including) end
	if start+1 >= end {
		return []string{}
	}

	// Extract the slice of planets between the two indices
	result := planets[start+1 : end]

	// Create a copy to avoid modifying the original planets slice if needed,
	// though in this specific logic, returning the slice is sufficient.
	return result
}
