```go
func Bf(planet1, planet2 string) []string {
	// Define the planets in order of proximity to the Sun
	planets := []string{"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"}

	// Helper function to find the index of a planet
	getIndex := func(name string) int {
		for i, p := range planets {
			if p == name {
				return i
			}
		}
		return -1
	}

	idx1 := getIndex(planet1)
	idx2 := getIndex(planet2)

	// Return empty slice if either planet name is invalid
	if idx1 == -1 || idx2 == -1 {
		return []string{}
	}

	// Determine the start and end indices to ensure we always 
	// iterate from the planet closer to the sun to the one further away
	start := idx1
	end := idx2
	if idx1 > idx2 {
		start = idx2
		end = idx1
	}

	// Collect planets strictly between the two indices
	var result []string
	for i := start + 1; i < end; i++ {
		result = append(result, planets[i])
	}

	// If no planets are between them, result will be nil/empty
	if result == nil {
		return []string{}
	}

	return result
}
