                result.push_back(current_word);
                current_word = ""; // Reset for the next word
            }
        } else {
            // Append character to the current word
            current_word += c;
        }
    }

    // Add the last word if the string didn't end with a delimiter
    if (!current_word.empty()) {
        result.push_back(current_word);
    }

