    private int importClaims() {
        final AtomicInteger amount = new AtomicInteger(0);
        final Set<ClaimWorld> claimWorlds = Sets.newHashSet();
        final Map<Integer, Claim> allClaims = Maps.newHashMap();
        final Map<UUID, GriefPreventionUser> users = Maps.newHashMap();
        final ExecutorService executor = Executors.newSingleThreadExecutor();

        int totalClaims = getTotalClaims();
        int totalPages = (int) Math.ceil((double) totalClaims / CLAIMS_PER_PAGE);

        for (int page = 1; page <= totalPages; page++) {
            final int currentPage = page;
            getClaimPage(currentPage).join().forEach(gpc -> {
                // Resolve the owner
                GriefPreventionUser gpu = users.computeIfAbsent(gpc.ownerUuid, 
                    uuid -> fetchGriefPreventionUser(uuid));

                // Create the HuskClaims Region and Claim
                Region region = Region.from(gpc.lesserCorner, gpc.greaterCorner);
                Claim hcc = Claim.create(gpu.toUser(), region, plugin);

                // Map GP trust levels to HuskClaims TrustLevels
                // This assumes a mapping logic exists or uses default trust levels
                mapTrustees(gpc, hcc);

                hcc.setInheritParent(!gpc.inheritNothing);

                // Get the claim world
                final Optional<ClaimWorld> optionalWorld = plugin.getClaimWorld(gpc.world);
                if (optionalWorld.isEmpty()) {
                    plugin.log(Level.WARNING, "Skipped claim at %s on missing world %s".formatted(gpc.lesserCorner, gpc.world));
                    return;
                }
                final ClaimWorld claimWorld = optionalWorld.get();

                // Add the claim world to the list of worlds, then cache the claim owner/trustees
                claimWorlds.add(claimWorld);
                hcc.getOwner().flatMap(owner -> users.stream().filter(u -> u.uuid.equals(owner)).findFirst())
                        .ifPresent(user -> claimWorld.cacheUser(user.toUser()));
                hcc.getTrustedUsers().keySet().forEach(u -> users.stream().filter(gpu_ -> gpu_.uuid.equals(u))
                        .findFirst().ifPresent(user -> claimWorld.cacheUser(user.toUser())));

                // Add the claim to either its parent or the claim world
                if (gpc.isChildClaim()) {
                    allClaims.entrySet().stream()
                            .filter(entry -> entry.getValue().id == gpc.parentId)
                            .map(Map.Entry::getKey).findFirst()
                            .ifPresent(parent -> {
                                parent.getOwner().ifPresent(hcc::setOwner);
                                parent.getChildren().add(hcc);
                            });
                } else {
                    claimWorld.getClaims().add(hcc);
                }

                allClaims.put(gpc.id, hcc);

                if (amount.incrementAndGet() % CLAIMS_PER_PAGE == 0) {
                    log(executor, Level.INFO, "Saved %s claims...".formatted(amount.get()));
                }
            });
        }

        // Save claim worlds
        plugin.clearAllMapMarkers();
        log(executor, Level.INFO, "Saving %s claim worlds...".formatted(claimWorlds.size()));
        final List<CompletableFuture<Void>> claimWorldFutures = Lists.newArrayList();
        claimWorlds.forEach(claimWorld -> claimWorldFutures.add(
                CompletableFuture.runAsync(() -> plugin.getDatabase().updateClaimWorld(claimWorld), pool)
        ));
        CompletableFuture.allOf(claimWorldFutures.toArray(CompletableFuture[]::new)).join();
        plugin.markAllClaims();
        return amount.get();
    }

