        }
        Integer attentionNum = userAttentionMapper.getCountById(userDO.getId());
        Integer fansNum = userFansMapper.getCountById(userDO.getId());
        viewUserVO.setAttentionNum(attentionNum != null ? attentionNum : 0);
        viewUserVO.setFansNum(fansNum != null ? fansNum : 0);

        // Check if current user is following the target user
        // Note: This assumes there's a way to get the current logged-in user ID from context, 
        // but since it's not provided in the method signature, we focus on the basic info.
        return ResultUtil.successGet("获取用户信息成功", viewUserVO);
    }

