        userDO.setPhoneNumber(registerInfoVO.getPhoneNumber());
        userDO.setPassword(Md5Util.getMd5(registerInfoVO.getPassword()));
        userDO.setNickname(registerInfoVO.getNickname());
        userDO.setAvatarUrl(registerInfoVO.getAvatarUrl());
        userDO.setUid(CodeUtil.createUid(registerInfoVO.getPhoneNumber()));
        userDO.setAccountStatus(0);
        return userDO;
    }
}
