```java
public class PostController extends BaseController
{
    @Autowired
    private IPostService postService;

    /**
     * 查询岗位信息列表
     */
    @GetMapping("/list")
    @ResponseBody
    public TableDataInfo list(Post post)
    {
        startPage();
        List<Post> list = postService.selectPostList(post);
        return getDataTable(list);
    }

    /**
     * 获取岗位详细信息
     */
    @GetMapping("/get/{postId}")
    @ResponseBody
    public AjaxResult getInfo(@PathVariable("postId") Long postId)
    {
        return success(postService.selectPostById(postId));
    }

    /**
     * 新增岗位信息
     */
    @Log(title = "岗位", businessType = BusinessType.INSERT)
    @PostMapping("/add")
    @ResponseBody
    public AjaxResult add(@Validated Post post)
    {
        String checkName = postService.checkPostNameUnique(post);
        if (StringUtils.isNotEmpty(checkName))
        {
            return error(checkName);
        }
        String checkCode = postService.checkPostCodeUnique(post);
        if (StringUtils.isNotEmpty(checkCode))
        {
            return error(checkCode);
        }
        return toAjax(postService.insertPost(post));
    }

    /**
     * 修改岗位信息
     */
    @Log(title = "岗位", businessType = BusinessType.UPDATE)
    @PostMapping("/edit")
    @ResponseBody
    public AjaxResult edit(@Validated Post post)
    {
        String checkName = postService.checkPostNameUnique(post);
        if (StringUtils.isNotEmpty(checkName))
        {
            return error(checkName);
        }
        String checkCode = postService.checkPostCodeUnique(post);
        if (StringUtils.isNotEmpty(checkCode))
        {
            return error(checkCode);
        }
        return toAjax(postService.updatePost(post));
    }

    /**
     * 删除岗位信息
     */
    @Log(title = "岗位", businessType = BusinessType.DELETE)
    @PostMapping("/remove")
    @ResponseBody
    public AjaxResult remove(Post post)
    {
        return toAjax(postService.deletePostByIds(post.getPostIds()));
    }

    /**
     * 导出岗位数据
     */
    @Log(title = "岗位", businessType = BusinessType.EXPORT)
    @GetMapping("/export")
    @ResponseBody
    public AjaxResult export(Post post)
    {
        List<Post> list = postService.selectPostList(post);
        ExcelUtil<Post> util = new ExcelUtil<>(Post.class);
        return util.exportExcel(list, "岗位数据");
    }

    /**
     * 导入岗位数据
     */
    @Log(title = "岗位", businessType = BusinessType.IMPORT)
    @PostMapping("/import")
    @ResponseBody
    public AjaxResult importData(MultipartFile file) throws Exception
    {
        List<Post> list = new ExcelUtil<>(Post.class).importExcel(file.getInputStream());
        for (Post post : list)
        {
            // 校验岗位名称
            String checkName = postService.checkPostNameUnique(post);
            if (StringUtils.isNotEmpty(checkName))
            {
                return error(checkName);
            }
            // 校验岗位编码
            String checkCode = postService.checkPostCodeUnique(post);
            if (StringUtils.isNotEmpty(checkCode))
            {
                return error(checkCode);
            }
            postService.insertPost(post);
        }
        return success();
    }
}
```

